from hep_lfx import HepComponent,component,payload
from lfx.io import DataInput,Output
from lfx.schema import Data
class AccessRefusalJoin(HepComponent):
 inputs=[DataInput(name='value',required=True,is_list=True)]
 outputs=[Output(name='result',method='build')]
 async def build(self)->Data:
  if not isinstance(self.value,list) or len(self.value)!=2:raise ValueError('REFUSED汇合输入必须为2')
  return Data(data=await component('refusalJoin',{'values':[payload(item) for item in self.value]},self._id))

